namespace HakutaiKagami.Core.Contracts;

public enum GuardKind { Escort, Suppression }
public enum GuardAction { Accept, Depart, Settle, Cancel }
public sealed record GuardInput(EntityId Id,GuardAction Action,EntityId? Job=null,EntityId? Issuer=null,GuardKind Kind=GuardKind.Escort,string? Destination=null);
public sealed record GuardTerms(EntityId Id,EntityId Worker,EntityId Issuer,EntityId Home,EntityId Destination,GuardKind Kind,long Fee,long Until);
public sealed record GuardOrder(GuardInput Input,long At,long Revision,GuardTerms? Terms,Intent? WorkerTrip,Intent? GuestTrip);
public sealed record GuardJob(GuardTerms Terms,string Phase,GuardOrder? Departure);
public static class GuardJobs
{
 public const string LandRoute="consenting-guard-job-land-trip-v1";
 internal static GuardOrder[] Orders(ContractWorld w)=>w.Bandits?.Jobs??[];
 static void Need(bool ok,string why){if(!ok)throw new InvalidDataException(why);}
 static bool Before(GuardOrder o,long at,long rev)=>o.At<at||o.At==at&&o.Revision<rev;
 public static GuardJob[] Jobs(ContractWorld w,long at=long.MaxValue,long rev=long.MaxValue){var jobs=new Dictionary<EntityId,GuardJob>();foreach(var o in Orders(w).Where(o=>Before(o,at,rev))){using var _cc=ControlContext.At(o.Revision);if(o.Terms is {} t){jobs.Add(t.Id,new(t,"引受中",null));continue;}var j=jobs[o.Input.Job!.Value];jobs[j.Terms.Id]=o.Input.Action switch{GuardAction.Depart=>j with{Phase="同行中",Departure=o},GuardAction.Settle=>j with{Phase="精算済み"},GuardAction.Cancel=>j with{Phase="取止め"},_=>throw new InvalidDataException("護衛の操作が不正です")};}return jobs.Values.ToArray();}
 public static bool Closed(GuardJob j)=>j.Phase is "精算済み" or "取止め";
 public static bool Reserved(ContractWorld w,EntityId actor,long at,long rev)=>Jobs(w,at,rev).Any(j=>!Closed(j)&&(j.Terms.Worker==actor||j.Terms.Kind==GuardKind.Escort&&j.Terms.Issuer==actor));
 public static long Net(ContractWorld w,EntityId wallet,long at,long rev){long sum=0;foreach(var o in Orders(w).Where(o=>Before(o,at,rev))){using var _cc=ControlContext.At(o.Revision);if(o.Terms is {} t){if(NewGameWork.Wallet(t.Issuer)==wallet)sum-=t.Fee;}else if(o.Input.Action is GuardAction.Settle or GuardAction.Cancel){var j=Jobs(w,o.At,o.Revision).Single(j=>j.Terms.Id==o.Input.Job);var receiver=o.Input.Action==GuardAction.Settle?j.Terms.Worker:j.Terms.Issuer;if(NewGameWork.Wallet(receiver)==wallet)sum+=j.Terms.Fee;}}return sum;}
 public static string[] Destinations(ContractWorld w,EntityId site){var from=NewGameWorld.Node(site.Value);return BranchRoutes.GraphEdges(w).Where(e=>!NationalRoutes.Sea(e.Id)&&(e.From==from||e.To==from)).Select(e=>e.From==from?e.To:e.From).Distinct().Order().ToArray();}
 public static EntityId[] Issuers(ContractWorld w){var site=SocialWorld.Site(w,w.PlayerControl);return w.Characters.Where(c=>c.Id!=w.PlayerControl&&c.Life==LifeState.Adult&&c.WillObey&&SocialWorld.Site(w,c.Id)==site&&!Reserved(w,c.Id,w.ElapsedSeconds,w.CommitSequence+1)&&!w.Tasks.Any(t=>t.Executor==c.Id&&t.FinishedAt==null)).Select(c=>c.Id).ToArray();}
 static Intent Trip(ContractWorld w,GuardTerms t,EntityId actor,EntityId id)=>TravelWorld.ActorMove(w,"request:guard-trip/"+id.Value.Replace(':','/')+"/"+actor.Value.Replace(':','/'),actor,NewGameWorld.Node(t.Destination.Value),true,LandRoute);
 public static bool IsTrip(ContractWorld w,Intent i)=>Orders(w).Any(o=>o.WorkerTrip==i||o.GuestTrip==i);
 internal static void ValidatePending(ContractWorld w,Intent i){var o=Orders(w).Single(x=>x.WorkerTrip==i||x.GuestTrip==i);var t=Jobs(w,o.At,o.Revision).Single(j=>j.Terms.Id==o.Input.Job).Terms;Need(i==Trip(w,t,i.Actor,o.Input.Id),"護衛の合意経路・時間が変わりました");}
 static bool Arrived(ContractWorld w,Intent? i,long at)=>i!=null&&w.Tasks.Any(t=>t.RequestId==i.RequestId&&t.Execution==ExecutionPhase.Completed&&t.FinishedAt<=at);
 static void Check(ContractWorld w,GuardOrder o){using var _cc=ControlContext.At(o.Revision);var i=o.Input;Need(BanditEncounter.Enabled(w)&&EntityId.IsValid(i.Id.Value)&&Enum.IsDefined(i.Action)&&Enum.IsDefined(i.Kind),"護衛依頼の入力が不正です");var jobs=Jobs(w,o.At,o.Revision);if(o.Terms is {} t){Need(i.Action==GuardAction.Accept&&i.Job==null&&t.Id==i.Id&&t.Worker==w.PlayerControl&&t.Issuer==i.Issuer&&t.Issuer!=t.Worker&&t.Kind==i.Kind&&t.Fee==80&&t.Until==o.At+30*86400&&o.WorkerTrip==null&&o.GuestTrip==null&&!jobs.Any(j=>!Closed(j)&&(j.Terms.Worker==t.Worker||j.Terms.Issuer==t.Issuer)),"依頼の原本・報酬・担当が不正です");Need(TransportWork.At(w,t.Worker,t.Home,o.At,o.Revision,true)&&TransportWork.At(w,t.Issuer,t.Home,o.At,o.Revision,true)&&w.Characters.Any(c=>c.Id==t.Issuer&&c.Life==LifeState.Adult&&c.WillObey)&&TransportWork.WalletBefore(w,t.Issuer,o.At,o.Revision)>=t.Fee,"現地の依頼主・合意・報酬がありません");Need(t.Kind==GuardKind.Suppression?t.Destination==t.Home&&i.Destination==null&&BanditEncounter.Camps.Contains(t.Home):i.Destination!=null&&t.Destination==RegionalCampaign.Site(i.Destination)&&Destinations(w,t.Home).Contains(i.Destination),"護衛は隣接する陸路、討伐は現地を対象にします");return;}
 Need(i.Job!=null&&i.Issuer==null&&i.Destination==null&&i.Kind==GuardKind.Escort,"引受原本を指定してください");var job=jobs.Single(j=>j.Terms.Id==i.Job);Need(!Closed(job),"精算済みです");var term=job.Terms;switch(i.Action){case GuardAction.Depart:Need(term.Kind==GuardKind.Escort&&job.Phase=="引受中"&&o.At<=term.Until&&TransportWork.At(w,term.Worker,term.Home,o.At,o.Revision,true)&&TransportWork.At(w,term.Issuer,term.Home,o.At,o.Revision,true),"本人と護衛対象が現地に揃っていません");var prior=PersonalCompanions.BeforeTask(w,new(new(o.Input.Id,term.Issuer,CompanionAction.TravelTogether),o.At,o.Revision,term.Home,null,null));Need(o.WorkerTrip==Trip(prior,term,term.Worker,o.Input.Id)&&o.GuestTrip==Trip(prior,term,term.Issuer,o.Input.Id),"当時の経路・時間を再現できません");Need(o.WorkerTrip!=null&&o.GuestTrip!=null&&o.WorkerTrip.Actor==term.Worker&&o.GuestTrip.Actor==term.Issuer&&o.WorkerTrip.DestinationSite==term.Destination&&o.GuestTrip.DestinationSite==term.Destination&&o.WorkerTrip.WorkSeconds==o.GuestTrip.WorkSeconds&&o.WorkerTrip.EffectiveAt==o.At&&o.GuestTrip.EffectiveAt==o.At&&o.WorkerTrip.RoutePolicy==LandRoute&&o.GuestTrip.RoutePolicy==LandRoute,"双方の実移動原本が一致しません");break;
 case GuardAction.Settle:Need(o.At<=term.Until&&TransportWork.At(w,term.Worker,term.Destination,o.At,o.Revision,true)&&TransportWork.At(w,term.Issuer,term.Destination,o.At,o.Revision,true),"現地の依頼主へ期限内に報告してください");Need(term.Kind==GuardKind.Suppression?w.Bandits!.Encounters.Any(e=>e.Actor==term.Worker&&e.Site==term.Destination&&e.Phase=="賊が敗走"&&e.LastAt<=o.At&&e.At>=Orders(w).Single(a=>a.Terms?.Id==term.Id).At):Arrived(w,job.Departure?.WorkerTrip,o.At)&&Arrived(w,job.Departure?.GuestTrip,o.At),"討伐の実績または双方の到着がありません");goto case GuardAction.Cancel;
 case GuardAction.Cancel:Need(o.WorkerTrip==null&&o.GuestTrip==null,"精算に移動原本は不要です");if(i.Action==GuardAction.Cancel)Need(PersonalCompanions.SiteAt(w,term.Worker,o.At,o.Revision) is {} site&&TransportWork.At(w,term.Issuer,site,o.At,o.Revision,true),"依頼主の現地で取止めを伝えてください");break;default:throw new InvalidDataException("護衛の操作が不正です");}}
 internal static void Apply(ContractWorld w,GuardInput i){GuardTerms? t=null;Intent? a=null,b=null;if(i.Action==GuardAction.Accept){Need(Issuers(w).Contains(i.Issuer??default),"仕事の空いた依頼主と現地で相談してください");var site=SocialWorld.Site(w,w.PlayerControl)??throw new InvalidDataException("到着してください");t=new(i.Id,w.PlayerControl,i.Issuer!.Value,site,i.Kind==GuardKind.Suppression?site:RegionalCampaign.Site(i.Destination??throw new InvalidDataException("行先がありません")),i.Kind,80,w.ElapsedSeconds+30*86400);}else if(i.Action==GuardAction.Depart){t=Jobs(w).Single(j=>j.Terms.Id==i.Job).Terms;Need(!BanditEncounter.Blocks(w)&&!BanditEncounter.NeedsContact(w),"先に道の入口の賊へ対処してください");a=Trip(w,t,t.Worker,i.Id);b=Trip(w,t,t.Issuer,i.Id);t=null;}var o=new GuardOrder(i,w.ElapsedSeconds,w.CommitSequence,t,a,b);Check(w,o);w.Bandits??=new(1,BanditEncounter.Policy,[],[]);w.Bandits=w.Bandits with{Jobs=[..Orders(w),o]};}
 public static void Validate(ContractWorld w,ContractWorld? prior){var orders=Orders(w);if(prior?.Bandits!=null)Need(orders.Take(prior.Bandits.Jobs.Length).SequenceEqual(prior.Bandits.Jobs),"過去の護衛依頼を変更できません");long rev=0,at=0;var ids=new HashSet<EntityId>();foreach(var o in orders){using var _cc=ControlContext.At(o.Revision);Need(ids.Add(o.Input.Id)&&!w.Bandits!.Decisions.Any(d=>d.Input.Id==o.Input.Id)&&o.Revision>rev&&o.Revision<=w.CommitSequence&&o.At>=at&&o.At<=w.ElapsedSeconds,"依頼の重複・順序が不正です");Check(w,o);if(prior==null&&o.Input.Action==GuardAction.Depart)Need(new[]{o.WorkerTrip,o.GuestTrip}.All(i=>i!=null&&w.Requests.Any(q=>q.Intent==i)),"護衛の移動原本が欠けています");rev=o.Revision;at=o.At;}}
}
public sealed partial class WorldSession
{
 public CommandResult ManageGuard(GuardInput i,long revision){lock(gate){var old=GuardJobs.Orders(state).SingleOrDefault(o=>o.Input.Id==i.Id);if(old!=null)return new(old.Input==i?ResultCode.AlreadyAccepted:ResultCode.IdPayloadConflict,i.Id,state.CommitSequence,"受付済みです");if(revision!=state.CommitSequence)return new(ResultCode.StateChanged,i.Id,state.CommitSequence,"表示を更新してください");if(NewGameWork.OwnIdUsed(state,i.Id)||state.Requests.Any(r=>r.Id==i.Id))return new(ResultCode.IdPayloadConflict,i.Id,state.CommitSequence,"使用済みの原本です");var before=state;try{Change(w=>GuardJobs.Apply(w,i));var order=GuardJobs.Orders(state).Single(o=>o.Input.Id==i.Id);foreach(var task in new[]{order.WorkerTrip,order.GuestTrip}.Where(t=>t!=null)){var result=Submit(task!,state.CommitSequence);if(result.Code!=ResultCode.Accepted){state=before;return new(ResultCode.NotAvailable,i.Id,state.CommitSequence,result.VisibleReason);}}return new(ResultCode.Accepted,i.Id,state.CommitSequence,"現地の依頼と報酬を記録しました");}catch(Exception e)when(e is InvalidDataException or InvalidOperationException or ArgumentException or OverflowException){state=before;return new(ResultCode.NotAvailable,i.Id,state.CommitSequence,e.Message);}}}
}
